let lang='en',regime='green';try{const saved=localStorage.getItem('orbit-language');if(languages.includes(saved))lang=saved;}catch{}
const pick=a=>a[languages.indexOf(lang)]||a[0];
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){
  const open=[...document.querySelectorAll('.chapter[open]')].map(d=>d.id);
  document.documentElement.lang=lang==='zh'?'zh-CN':lang;
  document.querySelectorAll('[data-key]').forEach(e=>e.textContent=copy[lang][e.dataset.key]);
  document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));
  document.getElementById('flowGrid').innerHTML=flows.map((f,i)=>`<button class="flow-node" data-chapter="${f.chapter}" type="button"><span class="step">0${i+1}</span><span class="arrow" aria-hidden="true">↗</span><h3>${safe(pick(f.title))}</h3><p>${safe(pick(f.text))}</p></button>`).join('');
  document.getElementById('chapters').innerHTML=chapters.map((c,i)=>`<details class="chapter" id="chapter-${i}" ${open.includes('chapter-'+i)?'open':''}><summary><span class="chapter-num">0${i+1}</span>${safe(pick(c.title))}</summary><div class="chapter-body">${c.body.map(p=>`<p>${safe(pick(p))}</p>`).join('')}<p class="our-note"><b>${copy[lang].note} · </b>${safe(pick(c.note))}</p></div></details>`).join('');
  document.getElementById('differences').innerHTML=differences.map(d=>`<div class="difference-item"><h3>${safe(pick(d.title))}</h3><p>${safe(pick(d.text))}</p></div>`).join('');
  document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const d=document.getElementById('chapter-'+b.dataset.chapter);d.open=true;d.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});d.querySelector('summary').focus({preventScroll:true});});
  calculate();
}
function calculate(){
  const t=copy[lang],host=document.getElementById('riskResult');
  document.querySelectorAll('[data-regime]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.regime===regime)));
  if(regime==='red'){host.innerHTML=`<p class="risk-invalid">${t.paused}</p>`;return;}
  const equity=Number(document.getElementById('equity').value),entry=Number(document.getElementById('entry').value),stop=Number(document.getElementById('stop').value);
  if(![equity,entry,stop].every(v=>Number.isFinite(v)&&v>0)||stop>=entry){host.innerHTML=`<p class="risk-invalid">${t.invalid}</p>`;return;}
  const budget=equity*(regime==='green'?.01:.005),distance=entry-stop,cap=.25*equity/entry,shares=Math.floor(Math.min(budget/distance,cap));
  const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});
  host.innerHTML=`<div class="risk-output"><strong>${shares.toLocaleString('en-US')}</strong> <span>${t.shares}</span><p>${t.budget}: ${money(budget)}</p><p>${t.planned}: ${money(shares*distance)}</p><p>${t.position}: ${money(shares*entry)}</p></div>${cap<budget/distance?`<p class="learn-muted">${t.cap}</p>`:''}${distance/entry>.07?`<p class="risk-invalid">${t.stopWarn}</p>`:''}`;
}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('orbit-language',lang);}catch{}render();});
document.querySelectorAll('[data-regime]').forEach(b=>b.onclick=()=>{regime=b.dataset.regime;calculate();});
document.getElementById('riskForm').addEventListener('input',calculate);document.getElementById('riskForm').addEventListener('submit',e=>e.preventDefault());
render();
